From 6bb297c28aa7609d3b85c0761a744064b5334ed0 Mon Sep 17 00:00:00 2001
From: Evan Miller 
Date: Sun, 29 Jan 2023 10:25:20 -0500
Subject: [PATCH] readstat_convert: Always strip trailing spaces

Supersedes #294
---
 src/readstat_convert.c | 2 +-
 1 file changed, 1 insertion(+), 1 deletion(-)

diff --git a/src/readstat_convert.c b/src/readstat_convert.c
index 1e54ca58..874cf973 100644
--- a/src/readstat_convert.c
+++ b/src/readstat_convert.c
@@ -7,7 +7,7 @@
 readstat_error_t readstat_convert(char *dst, size_t dst_len, const char *src, size_t src_len, iconv_t converter) {
     /* strip off spaces from the input because the programs use ASCII space
      * padding even with non-ASCII encoding. */
-    while (src_len && src[src_len-1] == ' ') {
+    while (src_len && (src[src_len-1] == ' ' || src[src_len-1] == '\0')) {
         src_len--;
     }
     if (dst_len == 0) {

